window.LIBRARY_CATALOG={"sections": [{"code": "L", "name": "Legends", "slug": "legends", "description": "Mythology, folklore, ghost stories, mysterious phenomena, and tales of the supernatural.", "note": ""}, {"code": "N", "name": "Natural Philosophy", "slug": "natural-philosophy", "description": "Biology, astronomy, physics, chemistry, geology, and the scientific study of nature.", "note": "Historical scientific works sit alongside modern textbooks. Some older explanations have been revised or rejected by modern science."}, {"code": "T", "name": "Theology", "slug": "theology", "description": "Sacred writings, spiritual philosophy, religious traditions, mysticism, and the nature of faith.", "note": "These descriptions present the teachings and claims of each tradition; they do not establish one tradition as objectively true in the campaign."}, {"code": "M", "name": "Medicine", "slug": "medicine", "description": "Anatomy, disease, emergency care, surgery, public health, and the study of the human body.", "note": "Historical medical works are preserved for study. Some contain incorrect or unsafe treatments and are not current treatment guides."}, {"code": "H", "name": "Histories", "slug": "histories", "description": "American and world history, government, warfare, civilization, and the lives of people who shaped history.", "note": "Older accounts reflect the perspectives and prejudices of their times. The collection includes modern textbooks, eyewitness accounts, and historical documents."}, {"code": "G", "name": "Maps & Travel", "slug": "maps-travel", "description": "American geography, highways, wilderness, railroads, exploration, and journeys across the real world.", "note": "These books concern Earth, especially the United States. They contain no maps of Mid-World or Gilead."}, {"code": "E", "name": "Engineering", "slug": "engineering", "description": "Mechanical construction, industrial machinery, electricity, manufacturing, transportation, and technological innovation.", "note": "Nineteen real-world technical and historical books, plus one NCP service entry for the Dogan replacement power supply."}], "books": [{"id": "L-001", "title": "Bulfinch's Mythology", "credit": "Thomas Bulfinch", "blurb": "An extensive collection of Greek, Roman, Norse, and medieval legends, including stories of Hercules, Perseus, the Trojan War, King Arthur, and Charlemagne. Readers discover how ancient cultures explained the world through gods, heroes, monsters, and supernatural forces. Many stories warn that extraordinary gifts often carry unexpected consequences.", "url": "https://www.gutenberg.org/ebooks/56644", "section": "L"}, {"id": "L-002", "title": "The Legend of Sleepy Hollow", "credit": "Washington Irving", "blurb": "The story of Ichabod Crane, a superstitious schoolteacher living near the Hudson River in New York. The region is haunted by tales of a headless horseman, and following a frightening nighttime encounter, Ichabod disappears. The story leaves readers to decide whether the horseman was a ghost or a human exploiting the town's fears.", "url": "https://www.gutenberg.org/ebooks/41", "section": "L"}, {"id": "L-003", "title": "Grimms' Fairy Tales", "credit": "Jacob and Wilhelm Grimm", "blurb": "A collection of traditional European folktales featuring witches, cursed objects, enchanted forests, talking animals, and bargains with supernatural beings. The original stories are frequently darker than modern retellings. Characters often suffer terrible consequences for broken promises, greed, or disobedience.", "url": "https://www.gutenberg.org/ebooks/2591", "section": "L"}, {"id": "L-004", "title": "Le Morte d'Arthur, Volume I", "credit": "Sir Thomas Malory", "blurb": "An account of the legendary King Arthur, Merlin, the Knights of the Round Table, and their adventures. The stories explore the establishment of Arthur's kingdom, the importance of chivalry, and the conflicts between duty, loyalty, and personal desire. Readers encounter a vision of kingship founded upon honor rather than brute strength.", "url": "https://www.gutenberg.org/ebooks/1251", "section": "L"}, {"id": "L-005", "title": "The Mabinogion", "credit": "Lady Charlotte Guest (translator)", "blurb": "A collection of medieval Welsh tales filled with kings, warriors, enchantments, transformations, and encounters with mysterious otherworldly beings. Several stories concern people crossing boundaries between the ordinary world and supernatural realms. Time, identity, and the consequences of promises do not always behave as expected.", "url": "https://www.gutenberg.org/ebooks/5160", "section": "L"}, {"id": "L-006", "title": "The Celtic Twilight", "credit": "W. B. Yeats", "blurb": "A collection of Irish folklore, supernatural accounts, and stories gathered from people who believed fairies and spirits still lived among them. The book describes mysterious disappearances, enchanted places, apparitions, and encounters with beings who appear human but are not. Much of the writing treats the supernatural with uncertainty rather than disbelief.", "url": "https://www.gutenberg.org/ebooks/10459", "section": "L"}, {"id": "L-007", "title": "Irish Fairy Tales", "credit": "James Stephens", "blurb": "Ten retellings of traditional Irish legends involving Fionn mac Cumhaill, ancient warriors, magical creatures, and supernatural transformations. The stories depict a world where heroes regularly encounter beings whose powers and motivations are difficult to understand. Cleverness can be as important as strength.", "url": "https://www.gutenberg.org/ebooks/2892", "section": "L"}, {"id": "L-008", "title": "Myths and Legends of the Great Plains", "credit": "Katharine Berry Judson (editor)", "blurb": "A collection of traditional stories from Indigenous peoples of the North American Great Plains, presented through an early twentieth-century editorial lens. The tales concern creation, animals, powerful beings, and relationships between humanity and the natural world. Readers encounter different explanations for how the world and its inhabitants came to exist.", "url": "https://www.gutenberg.org/ebooks/22083", "section": "L"}, {"id": "L-009", "title": "The Fairy-Faith in Celtic Countries", "credit": "W. Y. Evans-Wentz", "blurb": "A scholarly investigation into beliefs concerning fairies and supernatural beings throughout Celtic regions. The author collects accounts from individuals claiming personal encounters with these beings. Some witnesses describe hidden communities, unusual lights, mysterious disappearances, and places where the ordinary world seems to overlap another.", "url": "https://www.gutenberg.org/ebooks/34853", "section": "L"}, {"id": "L-010", "title": "The Arabian Nights Entertainments", "credit": "Andrew Lang (editor)", "blurb": "A collection of Middle Eastern and South Asian tales told within the framing story of Scheherazade, who tells stories to a king in order to postpone her execution. Readers encounter genies, magical objects, enchanted kingdoms, clever merchants, and dangerous bargains. Many stories illustrate how intelligence and patience overcome seemingly impossible circumstances.", "url": "https://www.gutenberg.org/ebooks/128", "section": "L"}, {"id": "L-011", "title": "The Golden Bough", "credit": "James George Frazer", "blurb": "A comparative study of magic, religion, and ritual traditions across historical societies. The author examines sacred kingship, fertility ceremonies, protective magic, taboos, and ritual sacrifice. Several chapters explore societies that believed the prosperity of their crops or communities depended upon the ceremonial death of an individual.", "url": "https://www.gutenberg.org/ebooks/3623", "section": "L"}, {"id": "L-012", "title": "The Legends of King Arthur and His Knights", "credit": "Sir James Knowles, adapting Thomas Malory", "blurb": "A retelling of Arthurian legends, including Merlin's prophecies, the sword in the stone, the formation of the Round Table, and the adventures of Arthur's knights. The book emphasizes honor, loyalty, prophecy, and the difficulties of maintaining a just kingdom. It presents a more accessible version of many stories found in Malory's longer work.", "url": "https://www.gutenberg.org/ebooks/12753", "section": "L"}, {"id": "L-013", "title": "The Wendigo", "credit": "Algernon Blackwood", "blurb": "A hunting party travels into the remote Canadian wilderness and encounters signs of an inexplicable presence. One member disappears after hearing a strange voice calling through the forest. The survivors begin to suspect that something ancient and inhuman inhabits the wilderness, capable of drawing people away from the familiar world.", "url": "https://www.gutenberg.org/ebooks/10897", "section": "L"}, {"id": "L-014", "title": "The Willows", "credit": "Algernon Blackwood", "blurb": "Two travelers canoeing along the Danube shelter on a remote island surrounded by willow trees. Strange sounds, unusual movements, and inexplicable events convince them that their surroundings may conceal an entirely different reality. They gradually fear that something beyond human understanding has noticed their presence.", "url": "https://www.gutenberg.org/ebooks/11438", "section": "L"}, {"id": "L-015", "title": "Ghost Stories of an Antiquary", "credit": "M. R. James", "blurb": "A collection of ghost stories involving scholars, old documents, cursed objects, abandoned places, and dangerous historical discoveries. Several characters encounter supernatural threats after investigating artifacts they do not fully understand. The stories frequently suggest that some knowledge is best left undisturbed.", "url": "https://www.gutenberg.org/ebooks/8486", "section": "L"}, {"id": "L-016", "title": "The Book of the Damned", "credit": "Charles Fort", "blurb": "A collection of reports concerning strange and supposedly unexplained phenomena, including unusual objects falling from the sky, mysterious lights, and anomalous scientific observations. Fort questions whether established scientific explanations account for every recorded event. His arguments are speculative, but the reports provide a fascinating collection of unusual claims.", "url": "https://www.gutenberg.org/ebooks/22472", "section": "L"}, {"id": "L-017", "title": "The King in Yellow", "credit": "Robert W. Chambers", "blurb": "A collection of stories, several revolving around a mysterious forbidden play known as The King in Yellow. Characters who encounter the play become obsessed, disturbed, or increasingly disconnected from ordinary reality. References to the Yellow Sign, Carcosa, and an enigmatic king recur throughout the opening tales.", "url": "https://www.gutenberg.org/ebooks/8492", "section": "L"}, {"id": "L-018", "title": "The House on the Borderland", "credit": "William Hope Hodgson", "blurb": "Two travelers discover a manuscript describing the experiences of a recluse living in an isolated house. The writer records encounters with monstrous creatures, visions of impossible landscapes, and experiences in which the passage of time becomes increasingly distorted. The narrative eventually expands into a terrifying vision of the universe's distant future.", "url": "https://www.gutenberg.org/ebooks/10002", "section": "L"}, {"id": "L-019", "title": "The Great God Pan", "credit": "Arthur Machen", "blurb": "A physician conducts a disturbing experiment intended to expose a person to a hidden aspect of reality. Years later, a series of strange events and unexplained tragedies appear connected to the experiment. The story explores the possibility that the human mind cannot safely perceive everything that exists.", "url": "https://www.gutenberg.org/ebooks/389", "section": "L"}, {"id": "L-020", "title": "A Book of Ghosts", "credit": "S. Baring-Gould", "blurb": "A collection of supernatural stories involving restless spirits, haunted places, strange coincidences, and encounters with the dead. The tales vary between unsettling, tragic, and occasionally humorous. Many concern ordinary people discovering that an apparently familiar place conceals an unusual history.", "url": "https://www.gutenberg.org/ebooks/36638", "section": "L"}, {"id": "N-001", "title": "On the Origin of Species", "credit": "Charles Darwin", "blurb": "Darwin presents evidence that species change over generations through natural selection. He examines inherited differences, competition, fossils, and the geographical distribution of living things. Readers learn how populations can gradually adapt to their environments and eventually diverge into distinct species.", "url": "https://www.gutenberg.org/ebooks/1228", "section": "N"}, {"id": "N-002", "title": "The Voyage of the Beagle", "credit": "Charles Darwin", "blurb": "A record of Darwin's travels aboard HMS Beagle, containing observations of wildlife, geology, landscapes, and human societies. The book explores how different environments support different organisms. Its descriptions of South America and the Galápagos Islands demonstrate how careful observation can lead to scientific discoveries.", "url": "https://www.gutenberg.org/ebooks/944", "section": "N"}, {"id": "N-003", "title": "The Descent of Man, and Selection in Relation to Sex", "credit": "Charles Darwin", "blurb": "Darwin applies evolutionary theory to human origins and examines the role of sexual selection in animals and humans. Readers encounter comparisons of anatomy, behavior, and inherited traits. The work is historically influential, although some of its nineteenth-century assumptions and claims about humanity are outdated.", "url": "https://www.gutenberg.org/ebooks/2300", "section": "N"}, {"id": "N-004", "title": "The Expression of the Emotions in Man and Animals", "credit": "Charles Darwin", "blurb": "An investigation of facial expressions, gestures, and emotional behavior in humans and animals. Darwin examines whether expressions such as fear, anger, surprise, and happiness have biological origins. Numerous observations and illustrations compare human reactions with those of other species.", "url": "https://www.gutenberg.org/ebooks/1227", "section": "N"}, {"id": "N-005", "title": "Relativity: The Special and General Theory", "credit": "Albert Einstein", "blurb": "Einstein explains how measurements of distance and time depend upon the circumstances of the observer. Through examples involving trains, light, gravity, and moving objects, he introduces special and general relativity. Readers discover that space and time are not the fixed, independent quantities they appear to be in everyday life.", "url": "https://www.gutenberg.org/ebooks/30155", "section": "N"}, {"id": "N-006", "title": "The Chemical History of a Candle", "credit": "Michael Faraday", "blurb": "A series of scientific lectures using an ordinary burning candle to explain chemistry and physics. Faraday demonstrates combustion, gases, heat, water, and the composition of air. The book shows how something familiar can reveal complex natural processes when examined carefully.", "url": "https://www.gutenberg.org/ebooks/14474", "section": "N"}, {"id": "N-007", "title": "The Story of the Heavens", "credit": "Robert Stawell Ball", "blurb": "An illustrated introduction to astronomy describing planets, moons, stars, comets, and the movements of celestial objects. Readers learn how astronomers used observation and mathematics to investigate the universe. The book offers a nineteenth-century understanding of astronomy, including theories subsequently revised by modern science.", "url": "https://www.gutenberg.org/ebooks/27378", "section": "N"}, {"id": "N-008", "title": "The Elements of Geology", "credit": "William Harmon Norton", "blurb": "A study of the processes that shape Earth's surface, including erosion, earthquakes, volcanoes, rivers, glaciers, and geological uplift. Illustrations explain how rocks and landscapes form over immense periods of time. Readers gain an understanding of how apparently permanent features of the world slowly change.", "url": "https://www.gutenberg.org/ebooks/40404", "section": "N"}, {"id": "N-009", "title": "Biology 2e", "credit": "OpenStax", "blurb": "A comprehensive modern biology textbook covering cells, genetics, evolution, ecology, and the diversity of life. Readers learn how living organisms reproduce, inherit characteristics, obtain energy, and interact with their environments. Detailed illustrations explain processes occurring from the microscopic level to entire ecosystems.", "url": "https://openstax.org/details/books/biology-2e", "section": "N"}, {"id": "N-010", "title": "Concepts of Biology", "credit": "OpenStax", "blurb": "An accessible introduction to biology for readers without advanced scientific training. Topics include cells, DNA, inheritance, evolution, ecosystems, and biodiversity. The book provides a practical foundation for understanding the differences between normal biological processes and unusual physical changes.", "url": "https://openstax.org/details/books/concepts-biology", "section": "N"}, {"id": "N-011", "title": "Astronomy 2e", "credit": "OpenStax", "blurb": "A modern examination of the universe, from the solar system to distant galaxies. Chapters discuss planetary motion, stars, gravity, black holes, cosmology, and the methods astronomers use to study distant objects. Readers discover how light carries information about places far beyond humanity's physical reach.", "url": "https://openstax.org/details/books/astronomy-2e", "section": "N"}, {"id": "N-012", "title": "Chemistry 2e", "credit": "OpenStax", "blurb": "An introductory chemistry textbook explaining atoms, molecules, chemical reactions, gases, solutions, and the behavior of matter. Readers learn how substances interact and why different materials possess different properties. The book includes examples of chemical processes encountered in ordinary life and industry.", "url": "https://openstax.org/details/books/chemistry-2e", "section": "N"}, {"id": "N-013", "title": "Chemistry: Atoms First 2e", "credit": "OpenStax", "blurb": "A chemistry textbook that begins with atomic structure and gradually builds toward more complex chemical relationships. Readers learn how electrons, chemical bonds, and molecular structures determine the behavior of substances. Its approach is particularly useful for understanding why materials react differently under the same conditions.", "url": "https://openstax.org/details/books/chemistry-atoms-first-2e", "section": "N"}, {"id": "N-014", "title": "College Physics 2e", "credit": "OpenStax", "blurb": "A broad introduction to the physical laws governing motion, forces, energy, electricity, waves, optics, and modern physics. The book combines mathematical examples with practical explanations. Readers discover how the same physical principles govern falling objects, electrical equipment, light, and sound.", "url": "https://openstax.org/details/books/college-physics-2e", "section": "N"}, {"id": "N-015", "title": "University Physics, Volume 1", "credit": "OpenStax", "blurb": "A calculus-based physics textbook concentrating on mechanics, motion, forces, energy, momentum, rotation, and waves. Its mathematical explanations are intended for serious scientific study. Readers learn how engineers and physicists predict the behavior of moving objects and mechanical systems.", "url": "https://openstax.org/details/books/university-physics-volume-1", "section": "N"}, {"id": "N-016", "title": "University Physics, Volume 2", "credit": "OpenStax", "blurb": "An advanced examination of thermodynamics, electricity, magnetism, and electromagnetic phenomena. Chapters explain electric fields, magnetic forces, electrical circuits, and the relationships between heat and energy. The book provides scientific background relevant to electrical machinery, though it contains no NCP-specific knowledge.", "url": "https://openstax.org/details/books/university-physics-volume-2", "section": "N"}, {"id": "N-017", "title": "University Physics, Volume 3", "credit": "OpenStax", "blurb": "A detailed examination of optics and modern physics, including relativity, quantum mechanics, atomic structure, and nuclear physics. Readers encounter scientific models explaining phenomena that cannot be adequately described by classical physics alone. The material is mathematically demanding.", "url": "https://openstax.org/details/books/university-physics-volume-3", "section": "N"}, {"id": "N-018", "title": "Microbiology", "credit": "OpenStax", "blurb": "A modern textbook examining bacteria, viruses, fungi, parasites, and other microscopic organisms. Readers learn how microbes reproduce, interact with their environments, and sometimes cause disease. The book also describes infection prevention, immunity, and the scientific methods used to identify microscopic threats.", "url": "https://openstax.org/details/books/microbiology", "section": "N"}, {"id": "N-019", "title": "Physics", "credit": "OpenStax", "blurb": "An introductory physics textbook explaining motion, gravity, forces, energy, electricity, and waves through practical examples. The material presents fundamental physical principles without assuming extensive mathematical knowledge. Readers can use it as a starting point before tackling the more advanced texts in this section.", "url": "https://openstax.org/details/books/physics", "section": "N"}, {"id": "N-020", "title": "Opticks", "credit": "Isaac Newton", "blurb": "Newton's experimental investigation into light, color, reflection, and refraction. He describes experiments involving prisms and lenses, demonstrating that white light contains different colors. The book illustrates how carefully controlled experiments can overturn long-established explanations of natural phenomena.", "url": "https://www.gutenberg.org/ebooks/33504", "section": "N"}, {"id": "T-001", "title": "The Holy Bible — King James Version", "credit": "Christian Scripture", "blurb": "A collection of writings concerning creation, ancient Israel, divine covenants, the life and teachings of Jesus Christ, and visions of final judgment. Readers encounter stories of miracles, prophets, sacrifices, wars, divine commandments, and the consequences of human choices. The Book of Revelation contains symbolic visions of a great struggle between good and evil.", "url": "https://www.gutenberg.org/ebooks/10900", "section": "T"}, {"id": "T-002", "title": "The Book of Mormon", "credit": "Latter-day Saint Scripture", "blurb": "A religious narrative concerning ancient peoples whose history begins with journeys from Jerusalem to the Americas. The book describes the rise and fall of civilizations, warfare, prophecy, faith, and moral responsibility. A central portion recounts Jesus Christ's ministry among people in the Americas following his resurrection.", "url": "https://www.churchofjesuschrist.org/study/scriptures/bofm?lang=eng", "section": "T"}, {"id": "T-003", "title": "The Qur'an", "credit": "Islamic Scripture", "blurb": "Islamic scripture emphasizing the oneness of God, moral accountability, mercy, judgment, and righteous living. Its chapters recount teachings concerning prophets, the responsibilities of humanity, and the relationship between divine guidance and human conduct. Repeated themes include compassion, justice, and the temporary nature of worldly power.", "url": "https://quran.com/", "section": "T"}, {"id": "T-004", "title": "The Bhagavad Gita", "credit": "Hindu Scripture", "blurb": "A philosophical dialogue between the warrior Arjuna and Krishna shortly before a great battle. Arjuna questions whether fighting his relatives and teachers can be morally justified. Krishna teaches him about duty, spiritual understanding, action, and the nature of the self.", "url": "https://www.gutenberg.org/ebooks/2388", "section": "T"}, {"id": "T-005", "title": "Tao Te Ching", "credit": "Laozi (traditionally attributed)", "blurb": "A philosophical work exploring harmony, simplicity, restraint, leadership, and the natural order. Its teachings frequently use paradox, suggesting that softness can overcome hardness and excessive control may create disorder. Readers encounter a vision of wisdom based on understanding the world rather than attempting to dominate it.", "url": "https://www.gutenberg.org/ebooks/216", "section": "T"}, {"id": "T-006", "title": "The Dhammapada", "credit": "Buddhist Scripture", "blurb": "A collection of teachings concerning morality, suffering, compassion, wisdom, and self-discipline. The text emphasizes how a person's intentions and actions shape their character. Readers encounter repeated warnings against anger, greed, hatred, and careless conduct.", "url": "https://www.gutenberg.org/ebooks/2017", "section": "T"}, {"id": "T-007", "title": "The Confessions of St. Augustine", "credit": "Augustine of Hippo", "blurb": "Augustine reflects upon his youth, moral failures, intellectual development, and conversion to Christianity. The book examines memory, desire, temptation, and humanity's relationship with God. One central question concerns why people sometimes knowingly choose actions they believe are wrong.", "url": "https://www.gutenberg.org/ebooks/3296", "section": "T"}, {"id": "T-008", "title": "The Pilgrim's Progress", "credit": "John Bunyan", "blurb": "An allegorical story following a traveler named Christian as he journeys from the City of Destruction toward the Celestial City. Along the road, he encounters temptations, dangerous places, false guides, and spiritual trials. His journey illustrates the difficulties of remaining faithful to a chosen path.", "url": "https://www.gutenberg.org/ebooks/131", "section": "T"}, {"id": "T-009", "title": "The Imitation of Christ", "credit": "Thomas à Kempis", "blurb": "A Christian devotional work emphasizing humility, self-discipline, contemplation, and following the example of Jesus Christ. The author argues that spiritual growth requires more than intellectual knowledge of religious teachings. Readers are encouraged to examine their conduct and cultivate an inward life of devotion.", "url": "https://www.gutenberg.org/ebooks/1653", "section": "T"}, {"id": "T-010", "title": "The Varieties of Religious Experience", "credit": "William James", "blurb": "A psychological examination of religious experiences, conversions, mystical visions, and personal transformations. James compares firsthand accounts from different traditions rather than attempting to prove a particular religion correct. Readers learn how spiritual experiences can profoundly affect human behavior and perceptions of reality.", "url": "https://www.gutenberg.org/ebooks/621", "section": "T"}, {"id": "T-011", "title": "The Upanishads", "credit": "Swami Paramananda (translation)", "blurb": "A collection of ancient Indian philosophical writings examining the self, ultimate reality, consciousness, and spiritual liberation. The texts explore the relationship between individual existence and a deeper universal principle. Readers encounter teachings that challenge ordinary assumptions about identity and the nature of existence.", "url": "https://www.gutenberg.org/ebooks/3283", "section": "T"}, {"id": "T-012", "title": "The Analects of Confucius", "credit": "Confucius and his disciples (traditionally attributed)", "blurb": "A collection of sayings and conversations concerning morality, education, leadership, family duties, and social harmony. Confucius emphasizes that good government depends upon the moral character of its leaders. Readers learn that authority should be accompanied by virtue, responsibility, and personal example.", "url": "https://www.gutenberg.org/ebooks/3330", "section": "T"}, {"id": "T-013", "title": "The Practice of the Presence of God", "credit": "Brother Lawrence", "blurb": "A collection of spiritual reflections concerning awareness of God during ordinary daily activities. Brother Lawrence describes treating humble work as an opportunity for devotion. Readers learn that spiritual discipline need not be confined to temples, formal prayers, or religious ceremonies.", "url": "https://www.gutenberg.org/ebooks/13871", "section": "T"}, {"id": "T-014", "title": "The Kybalion", "credit": "Three Initiates", "blurb": "An occult philosophical work presenting seven principles associated with its interpretation of Hermetic teachings. These include mentalism, correspondence, vibration, polarity, rhythm, cause and effect, and gender. The book claims that understanding these principles reveals hidden relationships throughout existence, although its historical claims about ancient wisdom are disputed.", "url": "https://www.gutenberg.org/ebooks/14209", "section": "T"}, {"id": "T-015", "title": "The Prophet", "credit": "Kahlil Gibran", "blurb": "A poetic work following a wise traveler preparing to leave a city where he has lived for many years. Before his departure, the inhabitants ask him to speak about love, work, suffering, freedom, friendship, and death. His responses offer philosophical reflections on the human condition.", "url": "https://www.gutenberg.org/ebooks/58585", "section": "T"}, {"id": "T-016", "title": "The Light of Asia", "credit": "Sir Edwin Arnold", "blurb": "A narrative poem recounting the life of Siddhartha Gautama and his journey toward enlightenment. The story follows a sheltered prince who encounters human suffering and abandons luxury in search of spiritual understanding. It presents Buddhist themes through a nineteenth-century English literary interpretation.", "url": "https://www.gutenberg.org/ebooks/8920", "section": "T"}, {"id": "T-017", "title": "The City of God, Volume I", "credit": "Augustine of Hippo", "blurb": "A theological and philosophical examination of civilization, history, divine purpose, and the relationship between worldly governments and spiritual devotion. Augustine responds to arguments blaming Christianity for Rome's decline. The book considers whether an earthly society can ever provide permanent security or justice.", "url": "https://www.gutenberg.org/ebooks/45304", "section": "T"}, {"id": "T-018", "title": "Doctrine and Covenants", "credit": "Latter-day Saint Scripture", "blurb": "A collection of revelations and declarations associated primarily with the founding and development of The Church of Jesus Christ of Latter-day Saints. Its sections discuss religious authority, covenants, church organization, moral conduct, and spiritual guidance. Several passages address the establishment of Zion and the responsibilities of a faithful community.", "url": "https://www.churchofjesuschrist.org/study/scriptures/dc-testament?lang=eng", "section": "T"}, {"id": "T-019", "title": "The Pearl of Great Price", "credit": "Latter-day Saint Scripture", "blurb": "A collection of religious writings including the Books of Moses and Abraham, selections from Joseph Smith's history, and the Articles of Faith. Its contents explore creation, prophecy, pre-earth existence, spiritual purpose, and the establishment of Zion. The Book of Moses includes an account of Enoch leading a righteous community.", "url": "https://www.churchofjesuschrist.org/study/scriptures/pgp?lang=eng", "section": "T"}, {"id": "T-020", "title": "Dialogues Concerning Natural Religion", "credit": "David Hume", "blurb": "A philosophical dialogue examining whether human reason and observations of nature can establish the existence or character of God. Three speakers debate arguments concerning design, suffering, and the limits of human knowledge. The book invites readers to question how confidently humanity can interpret the intentions of a divine being.", "url": "https://www.gutenberg.org/ebooks/4583", "section": "T"}, {"id": "M-001", "title": "Gray's Anatomy", "credit": "Author: Henry Gray", "blurb": "An extensive anatomical reference containing detailed illustrations of bones, muscles, nerves, blood vessels, organs, and tissues. Readers learn how the body's structures are arranged and how different systems connect. The illustrations demonstrate why even apparently minor injuries can damage important internal structures.", "url": "https://en.wikisource.org/wiki/Gray%27s_Anatomy", "section": "M"}, {"id": "M-002", "title": "The Merck Manual", "credit": "Publisher: Merck", "blurb": "A comprehensive medical reference covering diseases, symptoms, diagnosis, prevention, and treatment. Its entries discuss infections, neurological disorders, poisoning, injuries, and many other conditions. Readers can compare unfamiliar symptoms with established medical explanations, though identifying a disease requires considerably more than matching symptoms.", "url": "https://www.merckmanuals.com/home", "section": "M"}, {"id": "M-003", "title": "Where There Is No Doctor", "credit": "Author: David Werner and collaborators", "blurb": "A practical medical guide intended for communities with limited access to professional healthcare. It emphasizes sanitation, preventive care, clean water, recognizing illness, and responding appropriately to emergencies. Readers learn how important ordinary hygiene and basic medical knowledge become when hospitals and trained professionals are unavailable.", "url": "https://languages.hesperian.org/pages/en/pdf.html", "section": "M"}, {"id": "M-004", "title": "Anatomy and Physiology 2e", "credit": "Publisher: OpenStax", "blurb": "A modern textbook explaining the human body's structure and function. Chapters cover cells, tissues, organs, muscles, nerves, circulation, respiration, and other biological systems. Readers learn how the body maintains stable internal conditions and what happens when those systems become disrupted.", "url": "https://openstax.org/details/books/anatomy-and-physiology-2e", "section": "M"}, {"id": "M-005", "title": "Fundamentals of Nursing", "credit": "Publisher: OpenStax", "blurb": "An introduction to professional nursing and patient care. The book explains patient assessment, communication, infection prevention, safety, clinical judgment, and the responsibilities of healthcare providers. Readers discover that effective treatment depends upon careful observation and systematic decision-making.", "url": "https://openstax.org/details/books/fundamentals-nursing", "section": "M"}, {"id": "M-006", "title": "Medical-Surgical Nursing", "credit": "Publisher: OpenStax", "blurb": "A detailed textbook examining the care of adults experiencing serious medical and surgical conditions. Chapters describe the body's responses to illness, diagnostic procedures, and the management of complex health problems. The material emphasizes recognizing complications and understanding how conditions affect multiple body systems.", "url": "https://openstax.org/details/books/medical-surgical-nursing", "section": "M"}, {"id": "M-007", "title": "Clinical Nursing Skills", "credit": "Publisher: OpenStax", "blurb": "An instructional reference concerning the practical skills required in clinical healthcare. Readers encounter procedures for assessing patients, maintaining safety, preventing infection, and assisting people with different medical needs. Illustrations and explanations emphasize preparation, observation, and correct technique.", "url": "https://openstax.org/details/books/clinical-nursing-skills", "section": "M"}, {"id": "M-008", "title": "Pharmacology for Nurses", "credit": "Publisher: OpenStax", "blurb": "A textbook examining how medications affect the human body. Chapters explain drug classifications, interactions, adverse effects, and how medical professionals evaluate the risks associated with treatment. Readers learn that the same medication may affect individuals differently depending upon their health and other factors.", "url": "https://openstax.org/books/pharmacology/pages/1-introduction", "section": "M"}, {"id": "M-009", "title": "Maternal-Newborn Nursing", "credit": "Publisher: OpenStax", "blurb": "A medical textbook concerning pregnancy, childbirth, newborn development, and the care of parents and infants. It explains the physiological changes associated with pregnancy and birth, along with common complications. Readers gain an understanding of the specialized medical needs of newborns and recovering parents.", "url": "https://openstax.org/details/books/maternal-newborn-nursing", "section": "M"}, {"id": "M-010", "title": "Psychiatric-Mental Health Nursing", "credit": "Publisher: OpenStax", "blurb": "A textbook examining mental health, psychiatric conditions, psychological distress, and supportive clinical care. Chapters discuss assessment, recovery, communication, stigma, and evidence-based approaches to treatment. Readers learn that unusual behavior may have numerous psychological, neurological, medical, or environmental explanations.", "url": "https://openstax.org/books/psychiatric-mental-health/pages/1-introduction", "section": "M"}, {"id": "M-011", "title": "Nutrition for Nurses", "credit": "Publisher: OpenStax", "blurb": "A study of nutrition and its relationship to human health. The book explains digestion, essential nutrients, hydration, metabolism, and the effects of inadequate nutrition on different body systems. Readers learn how food and water shortages can gradually weaken an otherwise healthy population.", "url": "https://openstax.org/books/nutrition/pages/1-introduction", "section": "M"}, {"id": "M-012", "title": "Population Health for Nurses", "credit": "Publisher: OpenStax", "blurb": "A textbook focusing on public health and the wellbeing of communities rather than individual patients alone. Chapters examine disease prevention, epidemiology, environmental influences, and how health problems spread through populations. Readers discover why investigating the cause of an outbreak is essential before deciding how to contain it.", "url": "https://openstax.org/books/population-health/pages/1-introduction", "section": "M"}, {"id": "M-013", "title": "Clinical Methods: The History, Physical, and Laboratory Examinations", "credit": "Editors: H. Kenneth Walker, W. Dallas Hall, and J. Willis Hurst", "blurb": "A detailed medical reference concerning patient interviews, physical examinations, diagnostic tests, and clinical reasoning. Readers learn how healthcare professionals gather evidence and distinguish between possible causes of illness. The text emphasizes that a convincing explanation must be supported by reliable observations.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK201/", "section": "M"}, {"id": "M-014", "title": "Medical Microbiology, 4th Edition", "credit": "Editor: Samuel Baron", "blurb": "A medical textbook examining bacteria, viruses, fungi, parasites, and the mechanisms through which microorganisms cause disease. Chapters describe infection, immunity, diagnosis, epidemiology, and different classes of pathogens. Readers learn that illnesses may look similar while spreading through entirely different mechanisms.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK7627/", "section": "M"}, {"id": "M-015", "title": "Notes on Nursing: What It Is, and What It Is Not", "credit": "Author: Florence Nightingale", "blurb": "A historically influential examination of nursing care, cleanliness, ventilation, nutrition, and patient observation. Nightingale argues that the conditions surrounding a patient can greatly influence their recovery. Readers discover how careful attention to ordinary environmental factors helped transform nursing into a more systematic profession.", "url": "https://www.gutenberg.org/ebooks/17366", "section": "M"}, {"id": "M-016", "title": "The Care and Feeding of Children", "credit": "Author: L. Emmett Holt", "blurb": "An early twentieth-century medical reference concerning infant care, childhood development, hygiene, and nutrition. The book describes historical approaches to caring for children and monitoring their growth. Some recommendations are outdated, making it useful primarily as a record of medical understanding from its period.", "url": "https://www.gutenberg.org/ebooks/15484", "section": "M"}, {"id": "M-017", "title": "The People's Common Sense Medical Adviser in Plain English", "credit": "Author: R. V. Pierce", "blurb": "A nineteenth-century medical guide intended to make medicine understandable to ordinary families. Its chapters cover anatomy, hygiene, disease, and historical treatments. Readers discover how earlier physicians attempted to explain illness, including numerous ideas and remedies modern medicine no longer accepts.", "url": "https://www.gutenberg.org/ebooks/18467", "section": "M"}, {"id": "M-018", "title": "American Red Cross Text-Book on Home Hygiene and Care of the Sick", "credit": "Authors: Jane A. Delano and Anne Hervey Strong", "blurb": "A historical Red Cross guide concerning hygiene, caring for sick people at home, maintaining clean living conditions, and recognizing signs of illness. It reflects the medical needs and practices of the early twentieth century. The book illustrates the importance placed upon sanitation, caregiving, and community health during periods of limited medical access.", "url": "https://www.gutenberg.org/ebooks/32250", "section": "M"}, {"id": "M-019", "title": "Surgical Anatomy", "credit": "Author: Joseph Maclise", "blurb": "An illustrated surgical anatomy reference featuring detailed plates of the body's internal structures. The book examines the relationship between muscles, nerves, blood vessels, and areas of surgical interest. Readers gain an appreciation for how precisely anatomical structures must be understood when treating serious injuries.", "url": "https://www.gutenberg.org/ebooks/24440", "section": "M"}, {"id": "M-020", "title": "Anomalies and Curiosities of Medicine", "credit": "Authors: George M. Gould and Walter L. Pyle", "blurb": "A historical collection of extraordinary medical cases, rare anatomical conditions, unusual diseases, and reports of exceptional human physical characteristics. Some cases are well documented, while others reflect the limitations and sensationalism of nineteenth-century medicine. Readers encounter striking descriptions of how unusually the human body can sometimes develop or function.", "url": "https://www.gutenberg.org/ebooks/747", "section": "M"}, {"id": "H-001", "title": "U.S. History", "credit": "Publisher: OpenStax", "blurb": "A comprehensive history of the United States, from Indigenous North America and European colonization through independence, westward expansion, the Civil War, industrialization, and modern America. Readers learn how political, economic, technological, and social changes shaped the country. Maps and illustrations help explain the development of American cities, territories, and institutions.", "url": "https://openstax.org/details/books/us-history", "section": "H"}, {"id": "H-002", "title": "World History, Volume 1: to 1500", "credit": "Publisher: OpenStax", "blurb": "A history of human civilizations from their earliest development through approximately 1500 CE. Chapters explore ancient Mesopotamia, Egypt, Greece, Rome, India, China, Africa, and the Americas. Readers learn how agriculture, religion, trade, warfare, and political institutions influenced the growth of societies across the world.", "url": "https://openstax.org/details/books/world-history-volume-1", "section": "H"}, {"id": "H-003", "title": "World History, Volume 2: from 1400", "credit": "Publisher: OpenStax", "blurb": "An examination of world history from the fifteenth century into the modern era. Readers encounter the expansion of global trade, European colonialism, revolutions, industrialization, world wars, and international political movements. The book explains how distant civilizations became increasingly connected through commerce, technology, migration, and conflict.", "url": "https://openstax.org/details/books/world-history-volume-2", "section": "H"}, {"id": "H-004", "title": "Common Sense", "credit": "Author: Thomas Paine", "blurb": "A revolutionary pamphlet arguing that the American colonies should declare independence from Great Britain. Paine criticizes hereditary monarchy and challenges the idea that a distant king should possess authority over the lives of ordinary people. Readers discover how persuasive writing helped transform public opinion during the American Revolution.", "url": "https://www.gutenberg.org/ebooks/147", "section": "H"}, {"id": "H-005", "title": "The Federalist Papers", "credit": "Authors: Alexander Hamilton, James Madison, and John Jay", "blurb": "A collection of 85 essays defending the proposed United States Constitution. The authors examine federal authority, the separation of powers, political factions, representative government, and the dangers of concentrating power in a single institution. Readers learn how the American constitutional system was intended to balance effective government against the risk of tyranny.", "url": "https://www.gutenberg.org/ebooks/18", "section": "H"}, {"id": "H-006", "title": "History of the United States", "credit": "Authors: Charles A. Beard and Mary Ritter Beard", "blurb": "An early twentieth-century account of American history emphasizing politics, economics, settlement, industrial development, and social change. The book follows the nation from colonial times through the First World War. Readers learn how struggles over commerce, labor, territory, and political authority influenced American institutions.", "url": "https://www.gutenberg.org/ebooks/16960", "section": "H"}, {"id": "H-007", "title": "Democracy in America — Volume I", "credit": "Author: Alexis de Tocqueville", "blurb": "A French observer's examination of American government and society during the nineteenth century. Tocqueville describes local government, civic organizations, religion, democratic participation, and the growing importance of equality. Readers encounter both his admiration for American democracy and his concerns about conformity, individualism, and the possible tyranny of the majority.", "url": "https://www.gutenberg.org/ebooks/815", "section": "H"}, {"id": "H-008", "title": "The Education of Henry Adams", "credit": "Author: Henry Adams", "blurb": "An unusual autobiography written in the third person, describing Adams's attempts to understand a rapidly changing world. He examines politics, education, scientific discoveries, and the technological transformations of the nineteenth century. Readers discover how even highly educated observers struggled to comprehend the speed with which industrial civilization was changing.", "url": "https://www.gutenberg.org/ebooks/2044", "section": "H"}, {"id": "H-009", "title": "The Autobiography of Benjamin Franklin", "credit": "Author: Benjamin Franklin", "blurb": "Franklin recounts his early life, apprenticeship, career as a printer, and development into an influential American civic leader. He describes his efforts to improve his own character through a deliberate program of personal virtues. Readers gain insight into colonial American life, education, business, and the development of public institutions.", "url": "https://www.gutenberg.org/ebooks/148", "section": "H"}, {"id": "H-010", "title": "Narrative of the Life of Frederick Douglass, an American Slave", "credit": "Author: Frederick Douglass", "blurb": "Douglass recounts his experiences while enslaved, including violence, forced labor, efforts to prevent his education, and his determination to obtain freedom. Learning to read becomes a turning point in his understanding of his circumstances. Readers encounter a firsthand account of slavery's brutality and the struggle for personal liberty.", "url": "https://www.gutenberg.org/ebooks/23", "section": "H"}, {"id": "H-011", "title": "Incidents in the Life of a Slave Girl", "credit": "Author: Harriet Jacobs", "blurb": "Jacobs describes her life under slavery, the dangers she faced as a woman and mother, and her eventual escape. Her experiences include years spent hiding in an extremely confined space to avoid recapture. Readers learn about family separation, exploitation, resistance, and the extraordinary sacrifices enslaved parents sometimes made to protect their children.", "url": "https://www.gutenberg.org/ebooks/11030", "section": "H"}, {"id": "H-012", "title": "The Souls of Black Folk", "credit": "Author: W. E. B. Du Bois", "blurb": "A collection of essays examining African American life, education, political rights, and social inequality after emancipation. Du Bois introduces the concept of double consciousness, describing the experience of viewing oneself through both personal identity and the judgments of a prejudiced society. Readers learn about the continuing struggle for freedom and equality.", "url": "https://www.gutenberg.org/ebooks/408", "section": "H"}, {"id": "H-013", "title": "Up from Slavery", "credit": "Author: Booker T. Washington", "blurb": "Washington describes his journey from enslavement to becoming an influential educator and founder of the Tuskegee Institute. He emphasizes practical education, vocational skills, discipline, and economic self-sufficiency. Readers encounter his philosophy of social progress, which was influential but also debated by other civil rights thinkers.", "url": "https://www.gutenberg.org/ebooks/2376", "section": "H"}, {"id": "H-014", "title": "Twelve Years a Slave", "credit": "Author: Solomon Northup", "blurb": "Northup recounts how he was kidnapped while living as a free man in New York and sold into slavery in the American South. The book documents his experiences on Louisiana plantations, the cruelty of the institution, and his eventual recovery of freedom. Readers encounter a firsthand description of how quickly legal protection and personal liberty could be stripped away.", "url": "https://www.gutenberg.org/ebooks/45631", "section": "H"}, {"id": "H-015", "title": "How the Other Half Lives", "credit": "Author: Jacob A. Riis", "blurb": "An illustrated investigation into poverty and overcrowded housing in nineteenth-century New York City. Riis describes tenement conditions, immigration, poor sanitation, and the difficulties faced by working families. Readers learn how rapid urban growth created serious public health and social problems that wealthier residents frequently ignored.", "url": "https://www.gutenberg.org/ebooks/45502", "section": "H"}, {"id": "H-016", "title": "Twenty Years at Hull-House", "credit": "Author: Jane Addams", "blurb": "An autobiographical account of Addams's work at Hull-House, a community settlement in Chicago. The book describes education, social services, immigrant communities, labor concerns, and efforts to improve urban living conditions. Readers learn how neighborhood organizations attempted to address problems that government institutions often failed to resolve.", "url": "https://www.gutenberg.org/ebooks/1325", "section": "H"}, {"id": "H-017", "title": "Southern Horrors: Lynch Law in All Its Phases", "credit": "Author: Ida B. Wells-Barnett", "blurb": "An investigative work challenging the justifications used for racial lynching in the United States. Wells examines individual cases, exposes false accusations, and condemns the violence and intimidation used against Black communities. Readers learn how journalism and documented evidence were used to confront widespread injustice.", "url": "https://www.gutenberg.org/ebooks/14975", "section": "H"}, {"id": "H-018", "title": "The Red Record", "credit": "Author: Ida B. Wells-Barnett", "blurb": "A documented investigation of lynching in the United States during the nineteenth century. Wells gathers statistics, newspaper accounts, and individual cases to demonstrate patterns of racial violence. Readers discover how public narratives could conceal the actual motives and circumstances surrounding these crimes.", "url": "https://www.gutenberg.org/ebooks/14977", "section": "H"}, {"id": "H-019", "title": "The Shame of the Cities", "credit": "Author: Lincoln Steffens", "blurb": "A collection of investigative reports exposing political corruption in American cities. Steffens examines political machines, corrupt officials, business interests, and the role of public indifference. Readers learn how corruption can become embedded in ordinary institutions when powerful individuals benefit from preserving it.", "url": "https://www.gutenberg.org/ebooks/54710", "section": "H"}, {"id": "H-020", "title": "The Underground Railroad", "credit": "Author: William Still", "blurb": "A collection of firsthand accounts, letters, and historical records documenting people escaping slavery and those who assisted them. Still preserves the experiences of individuals risking capture, imprisonment, and death to reach freedom. Readers learn about the secret networks, courage, planning, and cooperation involved in these escapes.", "url": "https://www.gutenberg.org/ebooks/15263", "section": "H"}, {"id": "G-001", "title": "The Oregon Trail: Sketches of Prairie and Rocky-Mountain Life", "credit": "Francis Parkman", "blurb": "An account of Parkman's 1846 journey across the American frontier. The book describes wagon travel, prairie landscapes, buffalo hunting, frontier settlements, and encounters with Indigenous peoples. Readers learn about the physical difficulties of traveling across the Great Plains before railroads and modern highways transformed the region.", "url": "https://www.gutenberg.org/ebooks/1015", "section": "G"}, {"id": "G-002", "title": "Roughing It", "credit": "Mark Twain", "blurb": "A humorous, partly autobiographical account of Twain's travels through the American West during the nineteenth century. He describes stagecoach journeys, Nevada mining settlements, frontier speculation, and adventures in Hawaii. Readers encounter a mixture of genuine travel observations, exaggerated stories, and colorful descriptions of frontier life.", "url": "https://www.gutenberg.org/ebooks/3177", "section": "G"}, {"id": "G-003", "title": "Life on the Mississippi", "credit": "Mark Twain", "blurb": "Twain recounts his experiences learning to pilot steamboats on the Mississippi River and later returning to observe how the region had changed. The book describes river navigation, steamboat culture, river towns, and the challenges of understanding a constantly changing waterway. Readers discover how rivers once served as essential transportation networks.", "url": "https://www.gutenberg.org/ebooks/245", "section": "G"}, {"id": "G-004", "title": "American Notes", "credit": "Charles Dickens", "blurb": "Dickens's account of his travels through North America during the 1840s. He describes cities, transportation systems, prisons, public institutions, and the customs of the people he encounters. Readers discover how American society appeared to a visiting English writer, including his admiration for certain institutions and criticism of slavery and social conditions.", "url": "https://www.gutenberg.org/ebooks/675", "section": "G"}, {"id": "G-005", "title": "A Lady's Life in the Rocky Mountains", "credit": "Isabella L. Bird", "blurb": "A collection of letters describing Bird's travels through the Rocky Mountains during the 1870s. She recounts horseback journeys, difficult terrain, isolated settlements, and encounters with frontier residents. Her descriptions of Colorado's mountains and wilderness provide a vivid picture of travel before the region developed its modern roads and towns.", "url": "https://www.gutenberg.org/ebooks/755", "section": "G"}, {"id": "G-006", "title": "The Land of Little Rain", "credit": "Mary Austin", "blurb": "A series of essays describing the deserts and communities of California's Owens Valley and Mojave regions. Austin explores dry landscapes, scarce water, wildlife, desert plants, and the people who learned to survive there. Readers discover how life in an arid environment depends upon understanding seasonal changes and the locations of reliable water.", "url": "https://www.gutenberg.org/ebooks/365", "section": "G"}, {"id": "G-007", "title": "The Book of the National Parks", "credit": "Robert Sterling Yard", "blurb": "An illustrated guide to the national parks of the United States. The book describes famous landscapes, geological formations, mountains, canyons, and natural landmarks. Readers learn why these places were preserved and how their distinctive geological histories shaped the scenery visitors encounter.", "url": "https://www.gutenberg.org/ebooks/27513", "section": "G"}, {"id": "G-008", "title": "The Grand Canyon of Arizona: How to See It", "credit": "George Wharton James", "blurb": "An early twentieth-century travel guide to the Grand Canyon. The author describes viewpoints, trails, transportation, accommodations, and the canyon's enormous geological formations. Readers learn how visitors reached and explored the area before the development of modern tourist infrastructure.", "url": "https://www.gutenberg.org/ebooks/2394", "section": "G"}, {"id": "G-009", "title": "My First Summer in the Sierra", "credit": "John Muir", "blurb": "Muir recounts a summer traveling through California's Sierra Nevada while accompanying a flock of sheep into mountain pastures. His observations describe waterfalls, forests, wildflowers, animals, and steep mountain terrain. Readers encounter an intimate account of wilderness travel and the discoveries made through careful attention to nature.", "url": "https://www.gutenberg.org/ebooks/32540", "section": "G"}, {"id": "G-010", "title": "The Yosemite", "credit": "John Muir", "blurb": "A detailed description of Yosemite Valley and the surrounding mountains. Muir examines enormous granite cliffs, waterfalls, forests, glaciers, and the geological forces that shaped the region. Readers discover why Yosemite became one of America's most celebrated natural landscapes.", "url": "https://www.gutenberg.org/ebooks/7091", "section": "G"}, {"id": "G-011", "title": "The Mountains of California", "credit": "John Muir", "blurb": "An exploration of California's mountain ranges, particularly the Sierra Nevada. Muir describes high peaks, mountain forests, snowfields, lakes, and the creatures living at different elevations. Readers learn how climate, altitude, and geological processes influence the character of a mountain landscape.", "url": "https://www.gutenberg.org/ebooks/10012", "section": "G"}, {"id": "G-012", "title": "Travels in Alaska", "credit": "John Muir", "blurb": "Muir describes journeys through Alaska's coastal wilderness, including glaciers, fjords, forests, and remote settlements. His observations examine the enormous power of moving ice and the natural history of the region. Readers encounter descriptions of difficult travel through cold, rugged environments.", "url": "https://www.gutenberg.org/ebooks/7345", "section": "G"}, {"id": "G-013", "title": "Our National Parks", "credit": "John Muir", "blurb": "A collection of essays celebrating America's national parks and advocating for wilderness preservation. Muir describes Yellowstone, Yosemite, forests, wildlife, and other protected landscapes. Readers discover how these places were valued as natural wonders and why conservationists argued that they should remain protected from industrial development.", "url": "https://www.gutenberg.org/ebooks/60929", "section": "G"}, {"id": "G-014", "title": "Steep Trails", "credit": "John Muir", "blurb": "A collection of travel essays describing Muir's experiences across the American West, including California, Utah, Nevada, and the Grand Canyon. He recounts mountain journeys, desert landscapes, unusual weather, and encounters with wildlife. Readers see how different environments present different challenges to overland travel.", "url": "https://www.gutenberg.org/ebooks/326", "section": "G"}, {"id": "G-015", "title": "A Thousand-Mile Walk to the Gulf", "credit": "John Muir", "blurb": "An account of Muir's journey on foot from the Midwest toward the Gulf of Mexico. He describes towns, farms, forests, plants, animals, and the hardships of traveling long distances with limited possessions. Readers learn how a determined traveler experienced America's landscapes before modern automobile travel.", "url": "https://www.gutenberg.org/ebooks/60749", "section": "G"}, {"id": "G-016", "title": "On Sunset Highways: A Book of Motor Rambles in California", "credit": "Thomas D. Murphy", "blurb": "An early automobile travelogue describing journeys along California's developing road system. The author visits coastal towns, mountains, historic landmarks, and remote landscapes. Readers encounter an era when driving was still adventurous and road conditions could change dramatically between neighboring communities.", "url": "https://www.gutenberg.org/ebooks/57580", "section": "G"}, {"id": "G-017", "title": "Oregon, the Picturesque", "credit": "Thomas D. Murphy", "blurb": "A description of automobile journeys through Oregon and Northern California. The author visits Crater Lake, the Willamette Valley, Columbia River country, and other scenic regions. Readers learn about the roads, towns, natural landmarks, and practical difficulties encountered by early motorists exploring the Pacific Northwest.", "url": "https://www.gutenberg.org/ebooks/60359", "section": "G"}, {"id": "G-018", "title": "The Yellowstone National Park: Historical and Descriptive", "credit": "Hiram Martin Chittenden", "blurb": "A history and geographic description of Yellowstone National Park. The text examines early exploration, the establishment of the park, geysers, hot springs, wildlife, lakes, and important scenic routes. Readers learn about both the region's unusual geological activity and the challenges of preserving a vast wilderness area.", "url": "https://www.gutenberg.org/ebooks/42112", "section": "G"}, {"id": "G-019", "title": "Across the Plains, with Other Memories and Essays", "credit": "Robert Louis Stevenson", "blurb": "A collection beginning with Stevenson's account of traveling by emigrant train from New York toward San Francisco. He describes crowded railway cars, fellow passengers, changing landscapes, and the difficulties of long-distance rail travel. Other essays include recollections of California and reflections on places and people he encountered.", "url": "https://www.gutenberg.org/ebooks/614", "section": "G"}, {"id": "G-020", "title": "The Silverado Squatters", "credit": "Robert Louis Stevenson", "blurb": "Stevenson's account of living in an abandoned mining settlement in California's Napa Valley. He describes remote mountain life, abandoned industrial structures, local communities, and the challenges of surviving with limited comforts. Readers discover how quickly a once-busy settlement could become nearly deserted after its economic purpose disappeared.", "url": "https://www.gutenberg.org/ebooks/516", "section": "G"}, {"id": "E-001", "title": "Mechanical Drawing Self-Taught", "credit": "Author: Joshua Rose", "blurb": "A practical guide to representing mechanical objects through technical drawings. Readers learn how engineers use different views, measurements, and geometric methods to communicate the shapes of machine components. The book explains why accurate drawings are essential when different craftsmen must manufacture parts that fit together.", "url": "https://www.gutenberg.org/ebooks/23319", "section": "E"}, {"id": "E-002", "title": "Practical Mechanics for Boys", "credit": "Author: James Slough Zerbe", "blurb": "An introduction to mechanical construction, workshop practices, tools, and elementary engineering. The author explains how common mechanisms function and how materials can be shaped into useful objects. Readers discover the basic principles behind many devices encountered in workshops, farms, and factories.", "url": "https://www.gutenberg.org/ebooks/22298", "section": "E"}, {"id": "E-003", "title": "How It Works", "credit": "Author: Archibald Williams", "blurb": "An illustrated explanation of everyday machines and technological inventions. The book examines steam engines, electrical devices, transportation equipment, and other mechanical systems. Readers learn how complicated machinery often depends upon combinations of comparatively simple physical principles.", "url": "https://www.gutenberg.org/ebooks/28553", "section": "E"}, {"id": "E-004", "title": "The Notebooks of Leonardo da Vinci", "credit": "Author: Leonardo da Vinci", "blurb": "An extensive collection of Leonardo's observations, sketches, investigations, and mechanical concepts. The notebooks contain studies of architecture, anatomy, water movement, machines, and scientific phenomena. Readers encounter imaginative designs for devices that were extraordinary for their time, alongside detailed investigations of ordinary physical processes.", "url": "https://www.gutenberg.org/ebooks/5000", "section": "E"}, {"id": "E-005", "title": "De Re Metallica", "credit": "Author: Georgius Agricola", "blurb": "A sixteenth-century examination of mining, mineral extraction, metallurgy, and the machinery used in these industries. Detailed illustrations depict mine workings, water-powered machinery, furnaces, and methods of processing ores. Readers learn how complex industrial operations existed long before electrical power and modern manufacturing.", "url": "https://www.gutenberg.org/ebooks/38015", "section": "E"}, {"id": "E-006", "title": "Concrete Construction: Methods and Costs", "credit": "Authors: Halbert Powers Gillette and Charles Shattuck Hill", "blurb": "A technical study of concrete construction, including materials, formwork, mixing methods, equipment, labor, and costs. Readers learn how large construction projects organize workers and materials to produce durable structures. The book illustrates the relationship between engineering design and the practical realities of building.", "url": "https://www.gutenberg.org/ebooks/24855", "section": "E"}, {"id": "E-007", "title": "Electricity for Boys", "credit": "Author: James Slough Zerbe", "blurb": "An introductory explanation of electricity, magnetism, electrical circuits, and common electrical devices. The author uses simple examples and illustrations to explain concepts that were transforming everyday life during the early twentieth century. Readers gain an understanding of how electricity became useful for lighting, communication, and machinery.", "url": "https://www.gutenberg.org/ebooks/22766", "section": "E"}, {"id": "E-008", "title": "The Boy Electrician", "credit": "Author: Alfred Powell Morgan", "blurb": "An illustrated introduction to early electrical technology and amateur experimentation. Chapters explore batteries, motors, electromagnetism, communication equipment, and the development of electrical inventions. Readers discover the excitement surrounding electrical technology during a period when many familiar devices were still relatively new.", "url": "https://www.gutenberg.org/ebooks/63207", "section": "E"}, {"id": "E-009", "title": "The Standard Electrical Dictionary", "credit": "Author: T. O'Conor Sloane", "blurb": "A specialized dictionary explaining electrical terminology as understood during the late nineteenth century. Entries define technical concepts, instruments, discoveries, and inventions associated with electrical engineering. Readers can understand the language used in historical electrical publications, although some definitions reflect scientific knowledge that has since advanced.", "url": "https://www.gutenberg.org/ebooks/26535", "section": "E"}, {"id": "E-010", "title": "The Inventions, Researches and Writings of Nikola Tesla", "credit": "Editor: Thomas Commerford Martin", "blurb": "A collection documenting Nikola Tesla's research into electrical machinery, alternating current, motors, and related inventions. The book includes technical illustrations, descriptions of experiments, and discussions of Tesla's engineering work. Readers learn how electrical technology developed through experimentation, competing designs, and increasingly ambitious applications.", "url": "https://www.gutenberg.org/ebooks/39272", "section": "E"}, {"id": "E-011", "title": "Experiments with Alternate Currents of High Potential and High Frequency", "credit": "Author: Nikola Tesla", "blurb": "A record of Tesla's lectures and experiments involving high-frequency electrical phenomena. He describes unusual electrical discharges, lighting effects, and experimental apparatus. Readers gain a historical understanding of how scientists investigated the behavior of electricity under conditions that seemed extraordinary to contemporary observers.", "url": "https://www.gutenberg.org/ebooks/13476", "section": "E"}, {"id": "E-012", "title": "The Radio Amateur's Hand Book", "credit": "Author: A. Frederick Collins", "blurb": "An early twentieth-century introduction to wireless telegraphy and radio communication. The book explains the history of radio, basic transmitting and receiving equipment, antennas, and the principles underlying wireless signals. Readers learn how information can be communicated over considerable distances without a physical connection between sender and receiver.", "url": "https://www.gutenberg.org/ebooks/6935", "section": "E"}, {"id": "E-013", "title": "My Life and Work", "credit": "Authors: Henry Ford and Samuel Crowther", "blurb": "Henry Ford's account of automobile manufacturing, industrial organization, and his philosophy of production. He describes the development of automobile factories and the effort to make complicated products affordable through standardized manufacturing. Readers learn how mass production transformed industry, employment, and transportation.", "url": "https://www.gutenberg.org/ebooks/7213", "section": "E"}, {"id": "E-014", "title": "On the Economy of Machinery and Manufactures", "credit": "Author: Charles Babbage", "blurb": "An examination of industrial machinery, manufacturing processes, labor organization, and the economics of production. Babbage explains how machines and carefully organized workplaces can increase productivity. Readers encounter an early systematic study of the relationship between technology, human labor, and industrial efficiency.", "url": "https://www.gutenberg.org/ebooks/4238", "section": "E"}, {"id": "E-015", "title": "Passages from the Life of a Philosopher", "credit": "Author: Charles Babbage", "blurb": "An autobiographical account of Babbage's work and his attempts to develop sophisticated mechanical calculating machines. He describes scientific investigations, engineering difficulties, and disagreements surrounding the construction of his devices. Readers learn that the ambition to automate complex calculations existed long before electronic computers became practical.", "url": "https://www.gutenberg.org/ebooks/57532", "section": "E"}, {"id": "E-016", "title": "Edison: His Life and Inventions", "credit": "Authors: Frank Lewis Dyer and Thomas Commerford Martin", "blurb": "A biography of Thomas Edison emphasizing his experiments, inventions, laboratories, and business enterprises. The text discusses electric lighting, recorded sound, communications, and industrial research. Readers discover how technological breakthroughs depended upon experimentation, engineering teams, commercial investment, and extensive infrastructure.", "url": "https://www.gutenberg.org/ebooks/820", "section": "E"}, {"id": "E-017", "title": "Steam-ships: The Story of Their Development to the Present Day", "credit": "Author: R. A. Fletcher", "blurb": "A historical examination of steam-powered vessels and their development over time. The book describes advances in marine engines, ship construction, propulsion, and passenger transportation. Readers learn how maritime engineering allowed ships to become larger, faster, and less dependent upon wind.", "url": "https://www.gutenberg.org/ebooks/72847", "section": "E"}, {"id": "E-018", "title": "The Handbook of Soap Manufacture", "credit": "Authors: W. H. Simmons and H. A. Appleton", "blurb": "A specialized industrial reference describing the chemistry and manufacturing practices involved in soap production. The book examines raw materials, factory equipment, production methods, and quality control. Readers learn how an apparently ordinary household product can require substantial chemical and industrial knowledge to produce consistently.", "url": "https://www.gutenberg.org/ebooks/21724", "section": "E"}, {"id": "E-019", "title": "A Dictionary of Arts, Manufactures and Mines", "credit": "Author: Andrew Ure", "blurb": "A vast industrial reference describing manufacturing processes, mechanical devices, raw materials, and technical practices from the nineteenth century. Its entries explain numerous trades and industries, illustrating how complex and specialized manufacturing had become. Readers encounter the machinery, terminology, and working methods of an earlier industrial civilization", "url": "https://www.gutenberg.org/ebooks/44562", "section": "E"}, {"id": "E-020", "title": "Dogan Power Supply: Replacement Procedure", "credit": "North Central Positronics", "blurb": "An NCP service entry for replacing the Dogan power-supply module. The crew secures flow in and out with the flow-control valves, disconnects the output cabling and piping, replaces the device, reconnects the piping and cabling, and reopens the valves. The accompanying training film demonstrates the sequence.", "url": "lucien.html#power", "section": "E", "kind": "NCP service entry"}]};
